            )}
          </tbody>
        </table>
      </div>

      {/* Pagination Footer */}
      {totalPages > 1 && (
          <div className="p-4 bg-zinc-50 border-t border-zinc-100 flex justify-between items-center">
              <div className="text-xs text-gray-500">
                  Showing <span className="font-bold text-zinc-900">{Math.min(filteredLogs.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-900">{Math.min(filteredLogs.length, currentPage * itemsPerPage)}</span> of {filteredLogs.length} logs
              </div>
              <div className="flex items-center gap-2">
