    const [isLoading, setIsLoading] = useState(true);

    const deviceId = getDeviceId();

    // Map Settings for Database
    const mapSettingsPayload = (s: StoreSettings) => ({
        id: 'global_settings',
        name: s.name,
        address: s.address,
        contact_number: s.contactNumber,
        vat_rate: s.vatRate,
        gcash_number: s.gcashNumber,
        gcash_qr: s.gcashQr,
        receipt_header: s.receiptHeader,
        receipt_footer: s.receiptFooter,
        logo: s.logo,
        sms_enabled: s.smsEnabled,
        text_bee_api_key: s.textBeeApiKey,
        text_bee_device_id: s.textBeeDeviceId,
        email_enabled: s.emailEnabled,
        email_service_id: s.googleClientId, 
        email_template_id: s.googleClientSecret,
        email_public_key: s.googleRefreshToken,
        email_sender_name: s.emailSenderName,
        sms_template_upcoming: s.smsTemplateUpcoming,
        email_subject_upcoming: s.emailSubjectUpcoming,
        email_body_upcoming: s.emailBodyUpcoming,
        sms_template_waiting: s.smsTemplateWaiting,
        email_subject_waiting: s.emailSubjectWaiting,
        email_body_waiting: s.emailBodyWaiting,
        sms_template_ongoing: s.smsTemplateOngoing,
        email_subject_ongoing: s.emailSubjectOngoing,
        email_body_ongoing: s.emailBodyOngoing,
        sms_template_completed: s.smsTemplateCompleted,
        email_subject_completed: s.emailSubjectCompleted,
        email_body_completed: s.emailBodyCompleted,
        email_footer_text: s.emailFooterText,
        sms_template_promo: s.smsTemplatePromo,
        email_subject_promo: s.emailSubjectPromo,
        email_body_promo: s.emailBodyPromo
    });

    // Map Settings from Database to App
    const mapSettingsFromDb = (s: any): Partial<StoreSettings> => ({
        name: s.name,
        address: s.address,
        contactNumber: s.contact_number || s.contactNumber,
        vatRate: s.vat_rate || s.vatRate,
        gcashNumber: s.gcash_number || s.gcashNumber,
        gcashQr: s.gcash_qr || s.gcashQr,
        receiptHeader: s.receipt_header || s.receiptHeader,
        receiptFooter: s.receipt_footer || s.receiptFooter,
        logo: s.logo,
        smsEnabled: s.sms_enabled ?? false,
        textBeeApiKey: s.text_bee_api_key,
        textBeeDeviceId: s.text_bee_device_id,
        emailEnabled: s.email_enabled ?? false,
        googleClientId: s.email_service_id,
        googleClientSecret: s.email_template_id,
        googleRefreshToken: s.email_public_key,
        emailSenderName: s.email_sender_name,
        smsTemplateUpcoming: s.sms_template_upcoming || INITIAL_STORE_SETTINGS.smsTemplateUpcoming,
        emailSubjectUpcoming: s.email_subject_upcoming || INITIAL_STORE_SETTINGS.emailSubjectUpcoming,
        emailBodyUpcoming: s.email_body_upcoming || INITIAL_STORE_SETTINGS.emailBodyUpcoming,
        smsTemplateWaiting: s.sms_template_waiting || INITIAL_STORE_SETTINGS.smsTemplateWaiting,
        emailSubjectWaiting: s.email_subject_waiting || INITIAL_STORE_SETTINGS.emailSubjectWaiting,
        emailBodyWaiting: s.email_body_waiting || INITIAL_STORE_SETTINGS.emailBodyWaiting,
        smsTemplateOngoing: s.sms_template_ongoing || INITIAL_STORE_SETTINGS.smsTemplateOngoing,
        emailSubjectOngoing: s.email_subject_ongoing || INITIAL_STORE_SETTINGS.emailSubjectOngoing,
        emailBodyOngoing: s.email_body_ongoing || INITIAL_STORE_SETTINGS.emailBodyOngoing,
        smsTemplateCompleted: s.sms_template_completed || INITIAL_STORE_SETTINGS.smsTemplateCompleted,
        emailSubjectCompleted: s.email_subject_completed || INITIAL_STORE_SETTINGS.emailSubjectCompleted,
        emailBodyCompleted: s.email_body_completed || INITIAL_STORE_SETTINGS.emailBodyCompleted,
        emailFooterText: s.email_footer_text || INITIAL_STORE_SETTINGS.emailFooterText,
        smsTemplatePromo: s.sms_template_promo || INITIAL_STORE_SETTINGS.smsTemplatePromo,
        emailSubjectPromo: s.email_subject_promo || INITIAL_STORE_SETTINGS.emailSubjectPromo,
        emailBodyPromo: s.email_body_promo || INITIAL_STORE_SETTINGS.emailBodyPromo
    });

    // --- INITIAL DATA LOAD & SUBSCRIPTIONS ---
    useEffect(() => {
        const loadData = async () => {
            setIsLoading(true);
            try {
                const [
                    fetchedProducts, fetchedDiscounts, fetchedTransactions, 
                    fetchedAppointments, fetchedLogs, fetchedSettings, 
                    fetchedUsers, fetchedClients, fetchedDevices,
                    fetchedCategories, fetchedTemplateHistory
                ] = await Promise.all([
                    fetchTable('products'),
                    fetchTable('discounts'),
                    fetchTable('transactions'),
                    fetchTable('appointments'),
                    fetchTable('logs'),
                    fetchTable('settings'),
                    fetchTable('users'),
                    fetchTable('clients'),
                    fetchTable('devices'),
                    fetchTable('categories'),
                    fetchTable('template_history')
                ]);

                if (fetchedProducts) setProducts(fetchedProducts);
                if (fetchedDiscounts) setDiscounts(fetchedDiscounts);
                if (fetchedTransactions) setTransactions(fetchedTransactions);
                if (fetchedAppointments) setAppointments(fetchedAppointments);
                if (fetchedLogs) setLogs(fetchedLogs);
                if (fetchedUsers && fetchedUsers.length > 0) setUsers(fetchedUsers);
                if (fetchedClients) setClients(fetchedClients);
                if (fetchedDevices) setDevices(fetchedDevices);
                if (fetchedTemplateHistory) setTemplateHistory(fetchedTemplateHistory);

                if (fetchedSettings && fetchedSettings.length > 0) {
                    setStoreSettings(prev => ({ ...prev, ...mapSettingsFromDb(fetchedSettings[0]) }));
                }

                if (fetchedCategories) {
                    const prodCats = fetchedCategories.filter((c: any) => c.type === 'PRODUCT').map((c: any) => c.name);
                    const servCats = fetchedCategories.filter((c: any) => c.type === 'SERVICE').map((c: any) => c.name);
                    if (prodCats.length > 0) setProductCategories(prodCats);
                    if (servCats.length > 0) setServiceCategories(servCats);
                }

            } catch (error) {
                console.error("Failed to load initial data", error);
            } finally {
                setIsLoading(false);
            }
        };

        loadData();

        // Real-time subscriptions
        const subs = [
            subscribeToTable('products', (payload) => handleRealtime('products', payload, setProducts)),
            subscribeToTable('discounts', (payload) => handleRealtime('discounts', payload, setDiscounts)),
            subscribeToTable('transactions', (payload) => handleRealtime('transactions', payload, setTransactions)),
            subscribeToTable('appointments', (payload) => handleRealtime('appointments', payload, setAppointments)),
            subscribeToTable('logs', (payload) => handleRealtime('logs', payload, setLogs)),
            subscribeToTable('users', (payload) => handleRealtime('users', payload, setUsers)),
            subscribeToTable('clients', (payload) => handleRealtime('clients', payload, setClients)),
            subscribeToTable('devices', (payload) => handleRealtime('devices', payload, setDevices)),
            subscribeToTable('template_history', (payload) => handleRealtime('template_history', payload, setTemplateHistory)),
            subscribeToTable('settings', (payload) => {
                if (payload.new) {
                    setStoreSettings(prev => ({ ...prev, ...mapSettingsFromDb(payload.new) }));
                }
            }),
            subscribeToTable('categories', () => {
                // Refresh categories full list to ensure order/type correctness
                fetchTable('categories').then((cats: any) => {
                    if (cats) {
                        setProductCategories(cats.filter((c: any) => c.type === 'PRODUCT').map((c: any) => c.name));
                        setServiceCategories(cats.filter((c: any) => c.type === 'SERVICE').map((c: any) => c.name));
                    }
                });
            })
        ];

        return () => {
            subs.forEach(sub => sub.unsubscribe());
        };
    }, []);

    const handleRealtime = (table: string, payload: any, setter: React.Dispatch<React.SetStateAction<any[]>>) => {
        if (payload.eventType === 'INSERT') {
            setter(prev => [payload.new, ...prev]);
        } else if (payload.eventType === 'UPDATE') {
            setter(prev => prev.map(item => item.id === payload.new.id ? payload.new : item));
        } else if (payload.eventType === 'DELETE') {
            setter(prev => prev.filter(item => item.id !== payload.old.id));
        }
    };

    // --- ACTIONS ---

    const addLog = (action: string, details: string, referenceId?: string) => {
        const log: Log = {
            id: crypto.randomUUID(),
            action,
            details,
            timestamp: new Date().toISOString(),
            userId: currentUser ? currentUser.name : 'System',
            referenceId
        };
        // Optimistic Update
        setLogs(prev => [log, ...prev]);
        dbUpsert('logs', log);
    };

    const updateStoreSettings = (s: StoreSettings) => {
        setStoreSettings(s);
        dbUpsert('settings', mapSettingsPayload(s));
        addLog('SETTINGS', 'Updated store settings');
    };

    const checkAndIncrementSms = () => {
        const now = new Date();
        const currentHour = now.getHours();
        const currentDate = now.toISOString().split('T')[0];

        // Reset if hour or date changed
        if (smsUsage.lastSentHour !== currentHour || smsUsage.lastSentDate !== currentDate) {
            const newUsage = { count: 1, lastSentHour: currentHour, lastSentDate: currentDate };
            setSmsUsage(newUsage);
            save('smsUsage', newUsage);
            return true;
        }

        // Limit Check (Safe Hard Limit: 50/hour)
        if (smsUsage.count < 50) {
            const newUsage = { ...smsUsage, count: smsUsage.count + 1 };
            setSmsUsage(newUsage);
            save('smsUsage', newUsage);
            return true;
        }

        return false;
    };

    const addTransaction = (t: Transaction) => {
        // 1. Save Transaction
        setTransactions(prev => [t, ...prev]);
        dbUpsert('transactions', t);

        // 2. Update Stock
        t.items.forEach(item => {
            if (!item.isService) {
                const product = products.find(p => p.id === item.id);
                if (product) {
                    const newStock = product.stock - item.quantity;
                    const updatedProduct = { ...product, stock: newStock };
                    updateProduct(updatedProduct); // Re-uses DB update logic
                }
            }
        });

        addLog('POS', `Transaction #${t.id.slice(-4)}: ₱${t.total.toFixed(2)}`);
    };

    const deleteTransaction = (id: string) => {
        const tx = transactions.find(t => t.id === id);
        if (tx) {
            // Restore Stock
            tx.items.forEach(item => {
                if (!item.isService) {
                    const product = products.find(p => p.id === item.id);
                    if (product) {
                        const newStock = product.stock + item.quantity;
                        updateProduct({ ...product, stock: newStock });
                    }
                }
            });

            setTransactions(prev => prev.filter(t => t.id !== id));
            dbDelete('transactions', id);
            addLog('POS', `Deleted Transaction #${id.slice(-4)}`);
        }
    };

    const updateTransaction = (oldT: Transaction, newT: Transaction) => {
        // Restore old stock first
        oldT.items.forEach(item => {
            if (!item.isService) {
                const product = products.find(p => p.id === item.id);
                if (product) {
                    updateProduct({ ...product, stock: product.stock + item.quantity });
                }
            }
        });

        // Deduct new stock
        newT.items.forEach(item => {
            if (!item.isService) {
                const product = products.find(p => p.id === item.id);
                if (product) {
                    updateProduct({ ...product, stock: product.stock - item.quantity });
                }
            }
        });

        setTransactions(prev => prev.map(t => t.id === oldT.id ? newT : t));
        dbUpsert('transactions', newT);
        addLog('POS', `Updated Transaction #${newT.id.slice(-4)}`);
    };

    const addProduct = (p: Product) => {
        setProducts(prev => [...prev, p]);
        dbUpsert('products', p);
        addLog('INVENTORY', `Added ${p.name}`, p.id);
    };

    const updateProduct = (p: Product) => {
        setProducts(prev => prev.map(prod => prod.id === p.id ? p : prod));
        dbUpsert('products', p);
        // Note: We don't log every stock update from POS to avoid clutter, 
        // usually we log manual edits.
        if (products.find(old => old.id === p.id)?.stock !== p.stock) {
             // Optional: Log stock changes if significant
        }
    };

    const deleteProduct = (id: string) => {
        const p = products.find(i => i.id === id);
        setProducts(prev => prev.filter(prod => prod.id !== id));
        dbDelete('products', id);
        addLog('INVENTORY', `Deleted ${p?.name || 'Product'}`);
    };

    const addAppointment = (a: GroomingAppointment) => {
        setAppointments(prev => [...prev, a]);
        dbUpsert('appointments', a);
        addLog('GROOMING', `Booked: ${a.petName} (${a.serviceId})`);
    };

    const updateAppointment = (a: GroomingAppointment) => {
        setAppointments(prev => prev.map(apt => apt.id === a.id ? a : apt));
        dbUpsert('appointments', a);
        addLog('GROOMING', `Updated: ${a.petName}`);
    };

    const deleteAppointment = (id: string) => {
        setAppointments(prev => prev.filter(a => a.id !== id));
        dbDelete('appointments', id);
        addLog('GROOMING', `Cancelled appointment ${id.slice(-4)}`);
    };

    const updateAppointmentStatus = (id: string, status: 'SCHEDULED' | 'ONGOING' | 'COMPLETED') => {
        const apt = appointments.find(a => a.id === id);
        if (apt) {
            const updated = { ...apt, status };
            updateAppointment(updated);
            addLog('GROOMING', `Status ${status}: ${apt.petName}`);
        }
    };

    // --- USERS & AUTH ---
    const addUser = (u: User) => {
        setUsers(prev => [...prev, u]);
        dbUpsert('users', u);
        addLog('SETTINGS', `Added user ${u.name}`);
    };

    const editUser = (u: User) => {
        setUsers(prev => prev.map(user => user.id === u.id ? u : user));
        dbUpsert('users', u);
        addLog('SETTINGS', `Updated user ${u.name}`);
    };

    const deleteUser = (id: string) => {
        setUsers(prev => prev.filter(u => u.id !== id));
        dbDelete('users', id);
        addLog('SETTINGS', `Deleted user ${id}`);
    };

    const login = async (pin: string): Promise<boolean> => {
        // Find user by PIN verify
        // We need to verify against all users.
        for (const user of users) {
            if (user.pin) {
                if (user.pin.includes(':')) {
                    const [salt, hash] = user.pin.split(':');
                    const attemptHash = await hashPin(pin, salt);
                    if (attemptHash === hash) {
                        setCurrentUser(user);
                        save('currentUser', user);
                        addLog('LOGIN', `User ${user.name} logged in`);
                        return true;
                    }
                } else {
                    // Legacy PIN (plain text) - Should migrate eventually
                    if (user.pin === pin) {
                        setCurrentUser(user);
                        save('currentUser', user);
                        addLog('LOGIN', `User ${user.name} logged in`);
                        return true;
                    }
                }
            }
        }
        return false;
    };

    const logout = () => {
        if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`);
        setCurrentUser(null);
        save('currentUser', null);
    };

    // --- DEVICES ---
    const registerDevice = async () => {
        const info = getDeviceInfo();
        const net = await getNetworkInfo();

        const device: Device = {
            id: deviceId,
            name: info.name,
            os: info.os,
            browser: info.browser,
            device_type: info.device_type,
            status: users.length === 0 ? 'APPROVED' : 'PENDING', // Auto-approve if first device (setup)
            lastActive: new Date().toISOString(),
            ip: net.ip,
            location: net.location
        };

        dbUpsert('devices', device);
        // We don't set local state immediately, we wait for subscription to update 'devices' list
    };

    const updateDeviceStatus = (id: string, status: 'APPROVED' | 'BLOCKED' | 'PENDING', customName?: string) => {
        const device = devices.find(d => d.id === id);
        if (device) {
            const updated = { ...device, status, custom_name: customName || device.custom_name };
            dbUpsert('devices', updated);
            addLog('SETTINGS', `Device ${device.name} is now ${status}`);
        }
    };

    const deleteDevice = (id: string) => {
        dbDelete('devices', id);
        addLog('SETTINGS', `Removed device ${id}`);
    };

    const currentDevice = devices.find(d => d.id === deviceId);
    const currentDeviceStatus = currentDevice ? currentDevice.status : 'PENDING';

    // System is setup if there is at least one admin user
    const isSystemSetup = users.some(u => u.role === Role.ADMIN);

    // --- CLIENTS ---
    const addClient = (c: Client) => {
        setClients(prev => [...prev, c]);
        dbUpsert('clients', c);
        addLog('GROOMING', `Registered client ${c.name}`);
    };

    const updateClient = (c: Client) => {
        setClients(prev => prev.map(client => client.id === c.id ? c : client));
        dbUpsert('clients', c);
        addLog('GROOMING', `Updated client ${c.name}`);
    };

    const deleteClient = (id: string) => {
        setClients(prev => prev.filter(c => c.id !== id));
        dbDelete('clients', id);
        addLog('GROOMING', `Deleted client ${id}`);
    };

    // --- DISCOUNTS ---
    const addDiscount = (d: Discount) => {
        setDiscounts(prev => [...prev, d]);
        dbUpsert('discounts', d);
        addLog('SETTINGS', `Created promo ${d.name}`);
    };

    const toggleDiscount = (id: string) => {
        const d = discounts.find(x => x.id === id);
        if (d) {
            const updated = { ...d, active: !d.active };
            setDiscounts(prev => prev.map(x => x.id === id ? updated : x));
            dbUpsert('discounts', updated);
        }
    };

    const deleteDiscount = (id: string) => {
        setDiscounts(prev => prev.filter(d => d.id !== id));
        dbDelete('discounts', id);
    };

    // --- CATEGORIES ---
    const addProductCategory = (name: string) => {
        if (!productCategories.includes(name)) {
            setProductCategories(prev => [...prev, name]);
            dbUpsert('categories', { id: `PROD_${name}`, name, type: 'PRODUCT' });
        }
    };
    const editProductCategory = (oldName: string, newName: string) => {
        setProductCategories(prev => prev.map(c => c === oldName ? newName : c));
        // DB: Delete old, add new (Primary Key update workaround)
        dbDelete('categories', `PROD_${oldName}`);
        dbUpsert('categories', { id: `PROD_${newName}`, name: newName, type: 'PRODUCT' });
        // Update products
        products.forEach(p => {
            if (p.category === oldName && !p.isService) {
                updateProduct({ ...p, category: newName });
            }
        });
    };
    const deleteProductCategory = (name: string) => {
        setProductCategories(prev => prev.filter(c => c !== name));
        dbDelete('categories', `PROD_${name}`);
    };

    const addServiceCategory = (name: string) => {
        if (!serviceCategories.includes(name)) {
            setServiceCategories(prev => [...prev, name]);
            dbUpsert('categories', { id: `SERV_${name}`, name, type: 'SERVICE' });
        }
    };
    const editServiceCategory = (oldName: string, newName: string) => {
        setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));
        dbDelete('categories', `SERV_${oldName}`);
        dbUpsert('categories', { id: `SERV_${newName}`, name: newName, type: 'SERVICE' });
        products.forEach(p => {
            if (p.category === oldName && p.isService) {
                updateProduct({ ...p, category: newName });
            }
        });
    };
    const deleteServiceCategory = (name: string) => {
        setServiceCategories(prev => prev.filter(c => c !== name));
        dbDelete('categories', `SERV_${name}`);
    };

    // --- TEMPLATE HISTORY ---
    const saveTemplateHistory = (
        category: 'GROOMING' | 'PROMO', 
        channel: 'SMS' | 'EMAIL_SUBJECT' | 'EMAIL_BODY' | 'EMAIL_FOOTER', 
        content: string
    ) => {
        if (!content.trim()) return;
        const newHistory: TemplateHistory = {
            id: crypto.randomUUID(),
            category,
            channel,
            content,
            created_at: new Date().toISOString()
        };
        setTemplateHistory(prev => [newHistory, ...prev]);
        dbUpsert('template_history', newHistory);
    };

    const deleteTemplateHistory = (id: string) => {
        setTemplateHistory(prev => prev.filter(h => h.id !== id));
        dbDelete('template_history', id);
    };

    const value: StoreContextType = {
        currentUser, storeSettings, isLoading, smsUsage,
        products, discounts, transactions, appointments, logs, users, clients, devices,
        isSystemSetup, currentDeviceId: deviceId, currentDeviceStatus,
        templateHistory, productCategories, serviceCategories,
        login, logout,
        addTransaction, deleteTransaction, updateTransaction,
        addProduct, updateProduct, deleteProduct,
        addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus,
        addLog, checkAndIncrementSms, updateStoreSettings,
        saveTemplateHistory, deleteTemplateHistory,
        addUser, editUser, deleteUser,
        registerDevice, updateDeviceStatus, deleteDevice,
        addClient, updateClient, deleteClient,
        addDiscount, toggleDiscount, deleteDiscount,
        addProductCategory, editProductCategory, deleteProductCategory,
        addServiceCategory, editServiceCategory, deleteServiceCategory
    };

    return (
        <StoreContext.Provider value={value}>
            {children}
        </StoreContext.Provider>
    );
};

export const useStore = () => {
    const context = useContext(StoreContext);
    if (context === undefined) {
        throw new Error('useStore must be used within a StoreProvider');
    }
    return context;
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { 
    Product, User, Discount, Transaction, GroomingAppointment, 
    Log, StoreSettings, SmsUsage, Client, Role, Device, Category, TemplateHistory 
} from '../types';
import { 
    INITIAL_PRODUCTS, INITIAL_DISCOUNTS, INITIAL_TRANSACTIONS, 
    INITIAL_APPOINTMENTS, INITIAL_LOGS, INITIAL_STORE_SETTINGS, 
    INITIAL_USERS, INITIAL_PRODUCT_CATEGORIES, INITIAL_SERVICE_CATEGORIES 
} from '../constants';
import { 
    fetchTable, upsertData as dbUpsert, deleteData as dbDelete, 
    subscribeToTable 
} from '../services/supabase';
import { getDeviceId, getDeviceInfo, getNetworkInfo } from '../services/device';
import { save, load } from '../services/storage';
import { hashPin } from '../services/crypto';

interface StoreContextType {
    currentUser: User | null;
    storeSettings: StoreSettings;
    isLoading: boolean;
    smsUsage: SmsUsage;
    products: Product[];
    discounts: Discount[];
    transactions: Transaction[];
    appointments: GroomingAppointment[];
    logs: Log[];
    users: User[];
    clients: Client[];
    devices: Device[];
    isSystemSetup: boolean;
    currentDeviceId: string;
    currentDeviceStatus: 'PENDING' | 'APPROVED' | 'BLOCKED';
    templateHistory: TemplateHistory[];
    productCategories: string[];
    serviceCategories: string[];

    login: (pin: string) => Promise<boolean>;
    logout: () => void;

    addTransaction: (t: Transaction) => void;
    deleteTransaction: (id: string) => void;
    updateTransaction: (oldT: Transaction, newT: Transaction) => void;

    addProduct: (p: Product) => void;
    updateProduct: (p: Product) => void;
    deleteProduct: (id: string) => void;

    addAppointment: (a: GroomingAppointment) => void;
    updateAppointment: (a: GroomingAppointment) => void;
    deleteAppointment: (id: string) => void;
    updateAppointmentStatus: (id: string, status: 'SCHEDULED' | 'ONGOING' | 'COMPLETED') => void;

    addLog: (action: string, details: string, refId?: string) => void;

    checkAndIncrementSms: () => boolean;

    updateStoreSettings: (s: StoreSettings) => void;
    saveTemplateHistory: (category: 'GROOMING' | 'PROMO', channel: 'SMS' | 'EMAIL_SUBJECT' | 'EMAIL_BODY' | 'EMAIL_FOOTER', content: string) => void;
    deleteTemplateHistory: (id: string) => void;

    addUser: (u: User) => void;
    editUser: (u: User) => void;
    deleteUser: (id: string) => void;

    registerDevice: () => void;
    updateDeviceStatus: (id: string, status: 'APPROVED' | 'BLOCKED' | 'PENDING', customName?: string) => void;
    deleteDevice: (id: string) => void;

    addClient: (c: Client) => void;
    updateClient: (c: Client) => void;
    deleteClient: (id: string) => void;

    addDiscount: (d: Discount) => void;
    toggleDiscount: (id: string) => void;
    deleteDiscount: (id: string) => void;

    addProductCategory: (name: string) => void;
    editProductCategory: (oldName: string, newName: string) => void;
    deleteProductCategory: (name: string) => void;

    addServiceCategory: (name: string) => void;
    editServiceCategory: (oldName: string, newName: string) => void;
    deleteServiceCategory: (name: string) => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    // --- STATE DEFINITIONS ---
    const [currentUser, setCurrentUser] = useState<User | null>(load('currentUser', null));
    const [storeSettings, setStoreSettings] = useState<StoreSettings>(INITIAL_STORE_SETTINGS);
    const [smsUsage, setSmsUsage] = useState<SmsUsage>(load('smsUsage', { count: 0, lastSentHour: -1, lastSentDate: '' }));

    // Cloud Data States
    const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
    const [discounts, setDiscounts] = useState<Discount[]>(INITIAL_DISCOUNTS);
    const [transactions, setTransactions] = useState<Transaction[]>(INITIAL_TRANSACTIONS);
    const [appointments, setAppointments] = useState<GroomingAppointment[]>(INITIAL_APPOINTMENTS);
    const [logs, setLogs] = useState<Log[]>(INITIAL_LOGS);
    const [users, setUsers] = useState<User[]>(INITIAL_USERS);
    const [clients, setClients] = useState<Client[]>([]);
    const [devices, setDevices] = useState<Device[]>([]);
    const [templateHistory, setTemplateHistory] = useState<TemplateHistory[]>([]);

    // Category States
    const [productCategories, setProductCategories] = useState<string[]>(INITIAL_PRODUCT_CATEGORIES);
    const [serviceCategories, setServiceCategories] = useState<string[]>(INITIAL_SERVICE_CATEGORIES);

    const [isLoading, setIsLoading] = useState(true);

    const deviceId = getDeviceId();

    // Map Settings for Database
    const mapSettingsPayload = (s: StoreSettings) => ({
        id: 'global_settings',
        name: s.name,
        address: s.address,
        contact_number: s.contactNumber,
        vat_rate: s.vatRate,
        gcash_number: s.gcashNumber,
        gcash_qr: s.gcashQr,
        receipt_header: s.receiptHeader,
        receipt_footer: s.receiptFooter,
        logo: s.logo,
        sms_enabled: s.smsEnabled,
        text_bee_api_key: s.textBeeApiKey,
        text_bee_device_id: s.textBeeDeviceId,
        email_enabled: s.emailEnabled,
        email_service_id: s.googleClientId, 
        email_template_id: s.googleClientSecret,
        email_public_key: s.googleRefreshToken,
        email_sender_name: s.emailSenderName,
        sms_template_upcoming: s.smsTemplateUpcoming,
        email_subject_upcoming: s.emailSubjectUpcoming,
        email_body_upcoming: s.emailBodyUpcoming,
        sms_template_waiting: s.smsTemplateWaiting,
        email_subject_waiting: s.emailSubjectWaiting,
        email_body_waiting: s.emailBodyWaiting,
        sms_template_ongoing: s.smsTemplateOngoing,
        email_subject_ongoing: s.emailSubjectOngoing,
        email_body_ongoing: s.emailBodyOngoing,
        sms_template_completed: s.smsTemplateCompleted,
        email_subject_completed: s.emailSubjectCompleted,
        email_body_completed: s.emailBodyCompleted,
        email_footer_text: s.emailFooterText,
        sms_template_promo: s.smsTemplatePromo,
        email_subject_promo: s.emailSubjectPromo,
        email_body_promo: s.emailBodyPromo
    });

    // Map Settings from Database to App
    const mapSettingsFromDb = (s: any): Partial<StoreSettings> => ({
        name: s.name,
        address: s.address,
        contactNumber: s.contact_number || s.contactNumber,
        vatRate: s.vat_rate || s.vatRate,
        gcashNumber: s.gcash_number || s.gcashNumber,
        gcashQr: s.gcash_qr || s.gcashQr,
        receiptHeader: s.receipt_header || s.receiptHeader,
        receiptFooter: s.receipt_footer || s.receiptFooter,
        logo: s.logo,
        smsEnabled: s.sms_enabled ?? false,
        textBeeApiKey: s.text_bee_api_key,
        textBeeDeviceId: s.text_bee_device_id,
        emailEnabled: s.email_enabled ?? false,
        googleClientId: s.email_service_id,
        googleClientSecret: s.email_template_id,
        googleRefreshToken: s.email_public_key,
        emailSenderName: s.email_sender_name,
        smsTemplateUpcoming: s.sms_template_upcoming || INITIAL_STORE_SETTINGS.smsTemplateUpcoming,
        emailSubjectUpcoming: s.email_subject_upcoming || INITIAL_STORE_SETTINGS.emailSubjectUpcoming,
        emailBodyUpcoming: s.email_body_upcoming || INITIAL_STORE_SETTINGS.emailBodyUpcoming,
        smsTemplateWaiting: s.sms_template_waiting || INITIAL_STORE_SETTINGS.smsTemplateWaiting,
        emailSubjectWaiting: s.email_subject_waiting || INITIAL_STORE_SETTINGS.emailSubjectWaiting,
        emailBodyWaiting: s.email_body_waiting || INITIAL_STORE_SETTINGS.emailBodyWaiting,
        smsTemplateOngoing: s.sms_template_ongoing || INITIAL_STORE_SETTINGS.smsTemplateOngoing,
        emailSubjectOngoing: s.email_subject_ongoing || INITIAL_STORE_SETTINGS.emailSubjectOngoing,
        emailBodyOngoing: s.email_body_ongoing || INITIAL_STORE_SETTINGS.emailBodyOngoing,
        smsTemplateCompleted: s.sms_template_completed || INITIAL_STORE_SETTINGS.smsTemplateCompleted,
        emailSubjectCompleted: s.email_subject_completed || INITIAL_STORE_SETTINGS.emailSubjectCompleted,
        emailBodyCompleted: s.email_body_completed || INITIAL_STORE_SETTINGS.emailBodyCompleted,
        emailFooterText: s.email_footer_text || INITIAL_STORE_SETTINGS.emailFooterText,
        smsTemplatePromo: s.sms_template_promo || INITIAL_STORE_SETTINGS.smsTemplatePromo,
        emailSubjectPromo: s.email_subject_promo || INITIAL_STORE_SETTINGS.emailSubjectPromo,
        emailBodyPromo: s.email_body_promo || INITIAL_STORE_SETTINGS.emailBodyPromo
    });

    // --- INITIAL DATA LOAD & SUBSCRIPTIONS ---
    useEffect(() => {
        const loadData = async () => {
            setIsLoading(true);
            try {
                const [
                    fetchedProducts, fetchedDiscounts, fetchedTransactions, 
                    fetchedAppointments, fetchedLogs, fetchedSettings, 
                    fetchedUsers, fetchedClients, fetchedDevices,
                    fetchedCategories, fetchedTemplateHistory
                ] = await Promise.all([
                    fetchTable('products'),
                    fetchTable('discounts'),
                    fetchTable('transactions'),
                    fetchTable('appointments'),
                    fetchTable('logs'),
                    fetchTable('settings'),
                    fetchTable('users'),
                    fetchTable('clients'),
                    fetchTable('devices'),
                    fetchTable('categories'),
                    fetchTable('template_history')
                ]);

                if (fetchedProducts) setProducts(fetchedProducts);
                if (fetchedDiscounts) setDiscounts(fetchedDiscounts);
                if (fetchedTransactions) setTransactions(fetchedTransactions);
                if (fetchedAppointments) setAppointments(fetchedAppointments);
                if (fetchedLogs) setLogs(fetchedLogs);
                if (fetchedUsers && fetchedUsers.length > 0) setUsers(fetchedUsers);
                if (fetchedClients) setClients(fetchedClients);
                if (fetchedDevices) setDevices(fetchedDevices);
                if (fetchedTemplateHistory) setTemplateHistory(fetchedTemplateHistory);

                if (fetchedSettings && fetchedSettings.length > 0) {
                    setStoreSettings(prev => ({ ...prev, ...mapSettingsFromDb(fetchedSettings[0]) }));
                }

                if (fetchedCategories) {
                    const prodCats = fetchedCategories.filter((c: any) => c.type === 'PRODUCT').map((c: any) => c.name);
                    const servCats = fetchedCategories.filter((c: any) => c.type === 'SERVICE').map((c: any) => c.name);
                    if (prodCats.length > 0) setProductCategories(prodCats);
                    if (servCats.length > 0) setServiceCategories(servCats);
                }

            } catch (error) {
                console.error("Failed to load initial data", error);
            } finally {
                setIsLoading(false);
            }
        };

        loadData();

        // Real-time subscriptions
        const subs = [
            subscribeToTable('products', (payload) => handleRealtime('products', payload, setProducts)),
            subscribeToTable('discounts', (payload) => handleRealtime('discounts', payload, setDiscounts)),
            subscribeToTable('transactions', (payload) => handleRealtime('transactions', payload, setTransactions)),
            subscribeToTable('appointments', (payload) => handleRealtime('appointments', payload, setAppointments)),
            subscribeToTable('logs', (payload) => handleRealtime('logs', payload, setLogs)),
            subscribeToTable('users', (payload) => handleRealtime('users', payload, setUsers)),
            subscribeToTable('clients', (payload) => handleRealtime('clients', payload, setClients)),
            subscribeToTable('devices', (payload) => handleRealtime('devices', payload, setDevices)),
            subscribeToTable('template_history', (payload) => handleRealtime('template_history', payload, setTemplateHistory)),
            subscribeToTable('settings', (payload) => {
                if (payload.new) {
                    setStoreSettings(prev => ({ ...prev, ...mapSettingsFromDb(payload.new) }));
                }
            }),
            subscribeToTable('categories', () => {
                // Refresh categories full list to ensure order/type correctness
                fetchTable('categories').then((cats: any) => {
                    if (cats) {
                        setProductCategories(cats.filter((c: any) => c.type === 'PRODUCT').map((c: any) => c.name));
                        setServiceCategories(cats.filter((c: any) => c.type === 'SERVICE').map((c: any) => c.name));
                    }
                });
            })
        ];

        return () => {
            subs.forEach(sub => sub.unsubscribe());
        };
    }, []);

    // FIX: Check for duplicates before inserting
    const handleRealtime = (table: string, payload: any, setter: React.Dispatch<React.SetStateAction<any[]>>) => {
        if (payload.eventType === 'INSERT') {
            setter(prev => {
                // Critical Check: Duplicate Prevention
                if (prev.some(item => item.id === payload.new.id)) return prev;
                return [payload.new, ...prev];
            });
        } else if (payload.eventType === 'UPDATE') {
            setter(prev => prev.map(item => item.id === payload.new.id ? payload.new : item));
        } else if (payload.eventType === 'DELETE') {
            setter(prev => prev.filter(item => item.id !== payload.old.id));
        }
    };

    // --- ACTIONS ---

    const addLog = (action: string, details: string, referenceId?: string) => {
        const log: Log = {
            id: crypto.randomUUID(),
            action,
            details,
            timestamp: new Date().toISOString(),
            userId: currentUser ? currentUser.name : 'System',
            referenceId
        };
        // Optimistic Update
        setLogs(prev => [log, ...prev]);
        dbUpsert('logs', log);
    };

    const updateStoreSettings = (s: StoreSettings) => {
        setStoreSettings(s);
        dbUpsert('settings', mapSettingsPayload(s));
        addLog('SETTINGS', 'Updated store settings');
    };

    const checkAndIncrementSms = () => {
        const now = new Date();
        const currentHour = now.getHours();
        const currentDate = now.toISOString().split('T')[0];

        // Reset if hour or date changed
        if (smsUsage.lastSentHour !== currentHour || smsUsage.lastSentDate !== currentDate) {
            const newUsage = { count: 1, lastSentHour: currentHour, lastSentDate: currentDate };
            setSmsUsage(newUsage);
            save('smsUsage', newUsage);
            return true;
        }

        // Limit Check (Safe Hard Limit: 50/hour)
        if (smsUsage.count < 50) {
            const newUsage = { ...smsUsage, count: smsUsage.count + 1 };
            setSmsUsage(newUsage);
            save('smsUsage', newUsage);
            return true;
        }

        return false;
    };

    const addTransaction = (t: Transaction) => {
        // 1. Save Transaction
        setTransactions(prev => [t, ...prev]);
        dbUpsert('transactions', t);

        // 2. Update Stock
        t.items.forEach(item => {
            if (!item.isService) {
                const product = products.find(p => p.id === item.id);
                if (product) {
                    const newStock = product.stock - item.quantity;
                    const updatedProduct = { ...product, stock: newStock };
                    updateProduct(updatedProduct); // Re-uses DB update logic
                }
            }
        });

        addLog('POS', `Transaction #${t.id.slice(-4)}: ₱${t.total.toFixed(2)}`);
    };

    const deleteTransaction = (id: string) => {
        const tx = transactions.find(t => t.id === id);
        if (tx) {
            // Restore Stock
            tx.items.forEach(item => {
                if (!item.isService) {
                    const product = products.find(p => p.id === item.id);
                    if (product) {
                        const newStock = product.stock + item.quantity;
                        updateProduct({ ...product, stock: newStock });
                    }
                }
            });

            setTransactions(prev => prev.filter(t => t.id !== id));
            dbDelete('transactions', id);
            addLog('POS', `Deleted Transaction #${id.slice(-4)}`);
        }
    };

    const updateTransaction = (oldT: Transaction, newT: Transaction) => {
        // Restore old stock first
        oldT.items.forEach(item => {
            if (!item.isService) {
                const product = products.find(p => p.id === item.id);
                if (product) {
                    updateProduct({ ...product, stock: product.stock + item.quantity });
                }
            }
        });

        // Deduct new stock
        newT.items.forEach(item => {
            if (!item.isService) {
                const product = products.find(p => p.id === item.id);
                if (product) {
                    updateProduct({ ...product, stock: product.stock - item.quantity });
                }
            }
        });

        setTransactions(prev => prev.map(t => t.id === oldT.id ? newT : t));
        dbUpsert('transactions', newT);
        addLog('POS', `Updated Transaction #${newT.id.slice(-4)}`);
    };

    const addProduct = (p: Product) => {
        setProducts(prev => [...prev, p]);
        dbUpsert('products', p);
        addLog('INVENTORY', `Added ${p.name}`, p.id);
    };

    const updateProduct = (p: Product) => {
        setProducts(prev => prev.map(prod => prod.id === p.id ? p : prod));
        dbUpsert('products', p);
        // Note: We don't log every stock update from POS to avoid clutter, 
        // usually we log manual edits.
        if (products.find(old => old.id === p.id)?.stock !== p.stock) {
             // Optional: Log stock changes if significant
        }
    };

    const deleteProduct = (id: string) => {
        const p = products.find(i => i.id === id);
        setProducts(prev => prev.filter(prod => prod.id !== id));
        dbDelete('products', id);
        addLog('INVENTORY', `Deleted ${p?.name || 'Product'}`);
    };

    const addAppointment = (a: GroomingAppointment) => {
        setAppointments(prev => [...prev, a]);
        dbUpsert('appointments', a);
        addLog('GROOMING', `Booked: ${a.petName} (${a.serviceId})`);
    };

    const updateAppointment = (a: GroomingAppointment) => {
        setAppointments(prev => prev.map(apt => apt.id === a.id ? a : apt));
        dbUpsert('appointments', a);
        addLog('GROOMING', `Updated: ${a.petName}`);
    };

    const deleteAppointment = (id: string) => {
        setAppointments(prev => prev.filter(a => a.id !== id));
        dbDelete('appointments', id);
        addLog('GROOMING', `Cancelled appointment ${id.slice(-4)}`);
    };

    const updateAppointmentStatus = (id: string, status: 'SCHEDULED' | 'ONGOING' | 'COMPLETED') => {
        const apt = appointments.find(a => a.id === id);
        if (apt) {
            const updated = { ...apt, status };
            updateAppointment(updated);
            addLog('GROOMING', `Status ${status}: ${apt.petName}`);
        }
    };

    // --- USERS & AUTH ---
    const addUser = (u: User) => {
        setUsers(prev => [...prev, u]);
        dbUpsert('users', u);
        addLog('SETTINGS', `Added user ${u.name}`);
    };

    const editUser = (u: User) => {
        setUsers(prev => prev.map(user => user.id === u.id ? u : user));
        dbUpsert('users', u);
        addLog('SETTINGS', `Updated user ${u.name}`);
    };

    const deleteUser = (id: string) => {
        setUsers(prev => prev.filter(u => u.id !== id));
        dbDelete('users', id);
        addLog('SETTINGS', `Deleted user ${id}`);
    };

    const login = async (pin: string): Promise<boolean> => {
        // Find user by PIN verify
        // We need to verify against all users.
        for (const user of users) {
            if (user.pin) {
                if (user.pin.includes(':')) {
                    const [salt, hash] = user.pin.split(':');
                    const attemptHash = await hashPin(pin, salt);
                    if (attemptHash === hash) {
                        setCurrentUser(user);
                        save('currentUser', user);
                        addLog('LOGIN', `User ${user.name} logged in`);
                        return true;
                    }
                } else {
                    // Legacy PIN (plain text) - Should migrate eventually
                    if (user.pin === pin) {
                        setCurrentUser(user);
                        save('currentUser', user);
                        addLog('LOGIN', `User ${user.name} logged in`);
                        return true;
                    }
                }
            }
        }
        return false;
    };

    const logout = () => {
        if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`);
        setCurrentUser(null);
        save('currentUser', null);
    };

    // --- DEVICES ---
    const registerDevice = async () => {
        const info = getDeviceInfo();
        const net = await getNetworkInfo();

        const device: Device = {
            id: deviceId,
            name: info.name,
            os: info.os,
            browser: info.browser,
            device_type: info.device_type,
            status: users.length === 0 ? 'APPROVED' : 'PENDING', // Auto-approve if first device (setup)
            lastActive: new Date().toISOString(),
            ip: net.ip,
            location: net.location
        };

        dbUpsert('devices', device);
        // We don't set local state immediately, we wait for subscription to update 'devices' list
    };

    const updateDeviceStatus = (id: string, status: 'APPROVED' | 'BLOCKED' | 'PENDING', customName?: string) => {
        const device = devices.find(d => d.id === id);
        if (device) {
            const updated = { ...device, status, custom_name: customName || device.custom_name };
            dbUpsert('devices', updated);
            addLog('SETTINGS', `Device ${device.name} is now ${status}`);
        }
    };

    const deleteDevice = (id: string) => {
        dbDelete('devices', id);
        addLog('SETTINGS', `Removed device ${id}`);
    };

    const currentDevice = devices.find(d => d.id === deviceId);
    const currentDeviceStatus = currentDevice ? currentDevice.status : 'PENDING';

    // System is setup if there is at least one admin user
    const isSystemSetup = users.some(u => u.role === Role.ADMIN);

    // --- CLIENTS ---
    const addClient = (c: Client) => {
        setClients(prev => [...prev, c]);
        dbUpsert('clients', c);
        addLog('GROOMING', `Registered client ${c.name}`);
    };

    const updateClient = (c: Client) => {
        setClients(prev => prev.map(client => client.id === c.id ? c : client));
        dbUpsert('clients', c);
        addLog('GROOMING', `Updated client ${c.name}`);
    };

    const deleteClient = (id: string) => {
        setClients(prev => prev.filter(c => c.id !== id));
        dbDelete('clients', id);
        addLog('GROOMING', `Deleted client ${id}`);
    };

    // --- DISCOUNTS ---
    const addDiscount = (d: Discount) => {
        setDiscounts(prev => [...prev, d]);
        dbUpsert('discounts', d);
        addLog('SETTINGS', `Created promo ${d.name}`);
    };

    const toggleDiscount = (id: string) => {
        const d = discounts.find(x => x.id === id);
        if (d) {
            const updated = { ...d, active: !d.active };
            setDiscounts(prev => prev.map(x => x.id === id ? updated : x));
            dbUpsert('discounts', updated);
        }
    };

    const deleteDiscount = (id: string) => {
        setDiscounts(prev => prev.filter(d => d.id !== id));
        dbDelete('discounts', id);
    };

    // --- CATEGORIES ---
    const addProductCategory = (name: string) => {
        if (!productCategories.includes(name)) {
            setProductCategories(prev => [...prev, name]);
            dbUpsert('categories', { id: `PROD_${name}`, name, type: 'PRODUCT' });
        }
    };
    const editProductCategory = (oldName: string, newName: string) => {
        setProductCategories(prev => prev.map(c => c === oldName ? newName : c));
        // DB: Delete old, add new (Primary Key update workaround)
        dbDelete('categories', `PROD_${oldName}`);
        dbUpsert('categories', { id: `PROD_${newName}`, name: newName, type: 'PRODUCT' });
        // Update products
        products.forEach(p => {
            if (p.category === oldName && !p.isService) {
                updateProduct({ ...p, category: newName });
            }
        });
    };
    const deleteProductCategory = (name: string) => {
        setProductCategories(prev => prev.filter(c => c !== name));
        dbDelete('categories', `PROD_${name}`);
    };

    const addServiceCategory = (name: string) => {
        if (!serviceCategories.includes(name)) {
            setServiceCategories(prev => [...prev, name]);
            dbUpsert('categories', { id: `SERV_${name}`, name, type: 'SERVICE' });
        }
    };
    const editServiceCategory = (oldName: string, newName: string) => {
        setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));
        dbDelete('categories', `SERV_${oldName}`);
        dbUpsert('categories', { id: `SERV_${newName}`, name: newName, type: 'SERVICE' });
        products.forEach(p => {
            if (p.category === oldName && p.isService) {
                updateProduct({ ...p, category: newName });
            }
        });
    };
    const deleteServiceCategory = (name: string) => {
        setServiceCategories(prev => prev.filter(c => c !== name));
        dbDelete('categories', `SERV_${name}`);
    };

    // --- TEMPLATE HISTORY ---
    const saveTemplateHistory = (
        category: 'GROOMING' | 'PROMO', 
        channel: 'SMS' | 'EMAIL_SUBJECT' | 'EMAIL_BODY' | 'EMAIL_FOOTER', 
        content: string
    ) => {
        if (!content.trim()) return;
        const newHistory: TemplateHistory = {
            id: crypto.randomUUID(),
            category,
            channel,
            content,
            created_at: new Date().toISOString()
        };
        // Removed setTemplateHistory here to avoid race condition with Realtime subscription
        // setTemplateHistory(prev => [newHistory, ...prev]); 
        dbUpsert('template_history', newHistory);
    };

    const deleteTemplateHistory = (id: string) => {
        // Removed setTemplateHistory here to avoid race condition
        // setTemplateHistory(prev => prev.filter(h => h.id !== id));
        dbDelete('template_history', id);
    };

    const value: StoreContextType = {
        currentUser, storeSettings, isLoading, smsUsage,
        products, discounts, transactions, appointments, logs, users, clients, devices,
        isSystemSetup, currentDeviceId: deviceId, currentDeviceStatus,
        templateHistory, productCategories, serviceCategories,
        login, logout,
        addTransaction, deleteTransaction, updateTransaction,
        addProduct, updateProduct, deleteProduct,
        addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus,
        addLog, checkAndIncrementSms, updateStoreSettings,
        saveTemplateHistory, deleteTemplateHistory,
        addUser, editUser, deleteUser,
        registerDevice, updateDeviceStatus, deleteDevice,
        addClient, updateClient, deleteClient,
        addDiscount, toggleDiscount, deleteDiscount,
        addProductCategory, editProductCategory, deleteProductCategory,
        addServiceCategory, editServiceCategory, deleteServiceCategory
    };

    return (
        <StoreContext.Provider value={value}>
            {children}
        </StoreContext.Provider>
    );
};

export const useStore = () => {
    const context = useContext(StoreContext);
    if (context === undefined) {
        throw new Error('useStore must be used within a StoreProvider');
    }
    return context;
};

import React, { useState, useEffect, useRef } from 'react';
import { Settings as SettingsIcon, Dog, Upload, CreditCard, Cloud, Trash2, HardDrive, AlertCircle, Database, Bell, MessageSquare, Mail, CheckCircle, ExternalLink, Pencil, Smartphone, Monitor, Tag, Scissors, RotateCcw, History, ArrowRight, FileText } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import { supabase } from '../services/supabase';
import Button from '../components/ui/Button';
import { StoreSettings, TemplateHistory } from '../types';
import { generateGroomingEmailHtml } from '../services/notifications';
import { Dialog } from '@headlessui/react';

type ChannelView = 'SMS' | 'EMAIL';
type TemplateCategory = 'GROOMING' | 'PROMO';
type PromoScenario = 'PERCENTAGE' | 'FIXED' | 'MIN_SPEND' | 'ITEM_COUNT';

const Settings: React.FC = () => {
  const { storeSettings, updateStoreSettings, templateHistory, saveTemplateHistory, deleteTemplateHistory } = useStore();
  // formData tracks text fields for the "Edit" mode
  const [formData, setFormData] = useState<StoreSettings>(storeSettings);
