import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { SUPABASE_URL, SUPABASE_KEY } from '../constants';

// Initialize conditional client
// If credentials are missing, we return null to act as "Offline Mode"
export const supabase: SupabaseClient | null = (SUPABASE_URL && SUPABASE_KEY && SUPABASE_URL.startsWith('http')) 
    ? createClient(SUPABASE_URL, SUPABASE_KEY) 
    : null;

// Helper for Realtime Subscriptions
export const subscribeToTable = (
    table: string, 
    callback: (payload: any) => void
) => {
    if (!supabase) return { unsubscribe: () => {} };

    return supabase
        .channel(`public:${table}`)
        .on('postgres_changes', { event: '*', schema: 'public', table: table }, callback)
        .subscribe();
};

const isTableMissingError = (error: any) => {
    return (
        error.code === '42P01' || 
        error.message.includes('Could not find the table') || 
        (error.message.includes('relation') && error.message.includes('does not exist'))
    );
};

// Generic fetch
export const fetchTable = async (table: string) => {
    if (!supabase) return null;

    try {
        const { data, error } = await supabase.from(table).select('*');
        if (error) {
            if (!isTableMissingError(error)) {
                console.error(`Error fetching ${table}:`, error.message);
            }
            return null;
        }
        return data;
    } catch (e) {
        console.error(`Fetch exception for ${table}:`, e);
        return null;
    }
};

// Generic Upsert
export const upsertData = async (table: string, data: any) => {
    if (!supabase) return { error: { message: 'Offline mode' } };

    try {
        const options = data.id ? { onConflict: 'id' } : undefined;
        const { error } = await supabase.from(table).upsert(data, options);
        if (error) {
            if (!isTableMissingError(error)) {
                console.error(`Error upserting to ${table}:`, error.message);
            }
        }
        return { error };
    } catch (e: any) {
        console.error(`Upsert exception for ${table}:`, e.message || e);
        return { error: { message: 'Network Error' } };
    }
};

// Generic Delete
export const deleteData = async (table: string, id: string) => {
    if (!supabase) return { error: { message: 'Offline mode' } };

    try {
        const { error } = await supabase.from(table).delete().eq('id', id);
        if (error && !isTableMissingError(error)) {
            console.error(`Error deleting from ${table}:`, error.message);
        }
        return { error };
    } catch (e: any) {
        console.error(`Delete exception for ${table}:`, e.message || e);
        return { error: { message: 'Network Error' } };
    }
};

// Delete All (Clear Table)
export const clearTable = async (table: string) => {
    if (!supabase) return { error: { message: 'Offline mode' } };

    try {
        const { error } = await supabase.from(table).delete().not('id', 'is', null);
        if (error) {
            if (!isTableMissingError(error)) {
                console.error(`Error clearing ${table}:`, error.message);
                return { error };
            }
        }
        return { error: null };
    } catch (e: any) {
        console.error(`Clear table exception for ${table}:`, e.message || e);
        return { error: { message: 'Network Error' } };
    }
};

