        // Clean incoming data just in case
        textBeeApiKey: s.text_bee_api_key?.replace(/\s/g, ''),
        textBeeDeviceId: s.text_bee_device_id?.replace(/\s/g, ''),

        emailEnabled: s.email_enabled ?? false,
        emailSenderName: s.email_sender_name,

        // Read from Google columns, fallback to old email_ keys if necessary
        googleClientId: s.google_client_id?.trim() || s.email_service_id?.trim(),
        googleClientSecret: s.google_client_secret?.trim() || s.email_template_id?.trim(),
        googleRefreshToken: s.google_refresh_token?.trim() || s.email_public_key?.trim(),

