export const sendEmail = async (
    settings: StoreSettings, 
    to: string, 
    subject: string, 
    body: string, 
    title: string = "Notification"
) => {
    if (!settings.emailEnabled) {
        return { success: false, error: "Email disabled" };
    }

    const clientId = settings.googleClientId?.trim();
    const clientSecret = settings.googleClientSecret?.trim();
    const refreshToken = settings.googleRefreshToken?.trim();

    if (clientId && clientSecret && refreshToken) {
        try {
            // 1. Get Access Token
            const tokenResponse = await fetch('https://oauth2.googleapis.com/token', {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: new URLSearchParams({
                    client_id: clientId,
                    client_secret: clientSecret,
                    refresh_token: refreshToken,
                    grant_type: 'refresh_token',
                }),
            });

            const tokenData = await tokenResponse.json();
            if (!tokenData.access_token) {
                console.error("Google OAuth Error:", tokenData);
                throw new Error(`Failed to refresh Google token: ${tokenData.error_description || tokenData.error || 'Check Client ID/Secret/Refresh Token'}`);
            }

            // 2. Construct Email
            const htmlContent = generateGroomingEmailHtml(settings, body, title);

            const messageParts = [
                `From: "${settings.emailSenderName || settings.name}" <me>`,
                `To: ${to}`,
                `Subject: ${subject}`,
                'Content-Type: text/html; charset=utf-8',
                'MIME-Version: 1.0',
                '',
                htmlContent
            ];

            const rawMessage = btoa(unescape(encodeURIComponent(messageParts.join('\n'))))
                .replace(/\+/g, '-')
                .replace(/\//g, '_')
                .replace(/=+$/, '');

            // 3. Send via Gmail API
            const sendResponse = await fetch('https://gmail.googleapis.com/gmail/v1/users/me/messages/send', {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${tokenData.access_token}`,
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ raw: rawMessage }),
            });

            if (!sendResponse.ok) {
                const errorData = await sendResponse.json();
                console.error("Gmail API Send Error:", errorData);
                throw new Error(`Gmail API Send Failed: ${errorData.error?.message || 'Unknown error'}`);
            }
            return { success: true };

        } catch (e: any) {
            console.error("Email Send Error:", e);
            return { success: false, error: e.message || e };
        }
    }

    return { success: false, error: "No email provider configured" };
};

